<script setup lang="ts">
import {ref,computed,onBeforeUnmount,onMounted,watch} from 'vue';
import {teachingSteps,sceneDefinitions,type SceneId} from './teaching-models';
import {getLearning,putLearning} from './learning-store';
import {registerLearningFlush} from './learning-flush';
const props=defineProps<{sceneId:SceneId}>(),definition=computed(()=>sceneDefinitions[props.sceneId]);
const input=ref(JSON.stringify(definition.value.input)),steps=ref(teachingSteps(props.sceneId,definition.value.input)),index=ref(0),playing=ref(false),speed=ref(1),error=ref(''),loaded=ref(false);let timer:ReturnType<typeof setTimeout>|undefined;let disposed=false;
const step=computed(()=>steps.value[index.value]),key='teaching:'+props.sceneId;
const graph=computed(()=>{
 const nodes:{id:string;parent:string;label:string;x:number;y:number;active:boolean}[]=[];
 if(props.sceneId==='heap'){
  const values=step.value.values||[],depth=Math.max(1,Math.ceil(Math.log2(values.length+1))),width=Math.max(540,2**depth*46);
  for(let i=0;i<values.length;i++){const level=Math.floor(Math.log2(i+1)),first=2**level-1,slot=i-first,count=2**level;nodes.push({id:String(i),parent:i?String(Math.floor((i-1)/2)):'',label:String(values[i]),x:width*(slot+.5)/count,y:34+level*72,active:step.value.active?.includes(i)||false});}
  return {nodes,width,height:Math.max(150,depth*72+35)};
 }
 if(props.sceneId==='tree'||props.sceneId==='traversal'){
  for(const row of step.value.rows||[]){const parent=nodes.find(n=>n.id===String(row[1])),depth=parent?Math.round((parent.y-30)/65)+1:0;nodes.push({id:String(row[0]),parent:parent?.id||'',label:String(row[0]),x:parent?parent.x+(row[2]||1)*220/2**depth:300,y:30+depth*65,active:row[0]===step.value.variables['根']||row[0]===step.value.variables['当前节点']||step.value.active?.includes(row[0])||false});}
  return {nodes,width:600,height:Math.max(180,...nodes.map(n=>n.y+40))};
 }
 if(props.sceneId==='permutations'){
  const paths:number[][]=[[]],seen=new Set(['[]']);for(const s of steps.value.slice(0,index.value+1)){if(s.values&&!seen.has(JSON.stringify(s.values))){seen.add(JSON.stringify(s.values));paths.push(s.values);}}
  let x=20;const positions=new Map<string,number>();
  function position(path:number[]):number{const children=paths.filter(p=>p.length===path.length+1&&p.slice(0,-1).every((n,i)=>n===path[i]));const next=children.length?children.map(position):[x+=48];const value=(next[0]+next[next.length-1])/2;positions.set(JSON.stringify(path),value);return value;}position([]);
  for(const path of paths){const id=JSON.stringify(path);nodes.push({id,parent:path.length?JSON.stringify(path.slice(0,-1)):'',label:String(path.at(-1)??'起点'),x:positions.get(id)!,y:30+path.length*65,active:id===JSON.stringify(step.value.values||[])});}
  return {nodes,width:Math.max(300,x+30),height:Math.max(180,...nodes.map(n=>n.y+40))};
 }
 return {nodes,width:600,height:200};
});
function pause(){playing.value=false;clearTimeout(timer);}
async function save(){if(!loaded.value)return;try{await putLearning(key,{input:input.value,index:index.value,speed:speed.value});}catch{error.value='保存失败，输入和当前位置保留在本窗口。';}}
function apply(){pause();try{const result=teachingSteps(props.sceneId,JSON.parse(input.value));steps.value=result;index.value=0;error.value='';void save();}catch(e){error.value=String(e);}}
function next(delta=1){index.value=Math.max(0,Math.min(steps.value.length-1,index.value+delta));if(index.value===steps.value.length-1)pause();void save();}
function tick(){clearTimeout(timer);if(!playing.value)return;timer=setTimeout(()=>{next();tick();},1000/speed.value);}
function play(){if(playing.value){pause();return;}if(index.value===steps.value.length-1)index.value=0;playing.value=true;tick();}
function background(){if(document.hidden)pause();}
watch(speed,()=>{if(playing.value)tick();void save();});
onMounted(async()=>{const saved=await getLearning<{input:string;index:number;speed:number}|null>(key,null);if(disposed)return;if(saved){try{steps.value=teachingSteps(props.sceneId,JSON.parse(saved.input));input.value=saved.input;index.value=Math.max(0,Math.min(saved.index,steps.value.length-1));speed.value=[.5,1,2,4].includes(saved.speed)?saved.speed:1;}catch{}}loaded.value=true;document.addEventListener('visibilitychange',background);});
const unregister=registerLearningFlush(save);onBeforeUnmount(()=>{disposed=true;pause();unregister();void save();document.removeEventListener('visibilitychange',background);});
</script>
<template><section class="teaching-scene"><h2>{{definition.title}}</h2><p>教学演示 · 使用确定性算法模型，不追踪编辑器中的任意代码。</p><label v-if="sceneId!=='workflow'">{{definition.hint}}<textarea v-model="input" aria-label="教学演示输入" rows="3"/><button @click="apply">应用输入并重置</button></label><p v-if="error" role="alert">{{error}}</p>
<div class="teaching-controls"><button :disabled="index===0" @click="pause();next(-1)">上一步</button><button @click="play">{{playing?'暂停':'播放'}}</button><button :disabled="index===steps.length-1" @click="pause();next()">下一步</button><button @click="pause();index=0;save();play()">重新播放</button><label>速度<select v-model.number="speed"><option :value=".5">0.5×</option><option :value="1">1×</option><option :value="2">2×</option><option :value="4">4×</option></select></label><span>{{index+1}} / {{steps.length}}</span></div>
<div class="teaching-stage"><svg v-if="graph.nodes.length" :viewBox="`0 0 ${graph.width} ${graph.height}`" :style="{width:graph.width+'px',minWidth:Math.min(graph.width,500)+'px',maxWidth:'none',height:graph.height+'px'}" role="img" :aria-label="step.explanation"><g v-for="node in graph.nodes" :key="node.id"><line v-if="node.parent" :x1="graph.nodes.find(n=>n.id===node.parent)?.x" :y1="graph.nodes.find(n=>n.id===node.parent)?.y" :x2="node.x" :y2="node.y" stroke="#6c9bb6" stroke-width="2"/><circle :cx="node.x" :cy="node.y" r="18" :fill="node.active?'#a77d35':'#214052'" stroke="#96d0dd"/><text :x="node.x" :y="node.y+5" fill="white" text-anchor="middle" font-size="12">{{node.label}}</text></g></svg><div v-if="sceneId==='hanoi'" class="hanoi-towers"><div v-for="(tower,i) in step.rows" :key="i"><strong>{{['A','B','C'][i]}}</strong><span v-for="ring in [...tower].reverse()" :key="ring" :style="{width:24+ring*20+'px'}">{{ring}}</span><small v-if="!tower.length">空柱</small></div></div><div v-if="step.values" class="teaching-values" :class="{'stack-display':sceneId==='stack','queue-display':sceneId==='queue','deque-display':sceneId==='deque','hash-display':sceneId==='hash','traversal-display':sceneId==='traversal'}"><div v-for="(value,i) in step.values" :key="i" :class="{active:step.active?.includes(i),empty:sceneId==='hash'&&value<0}"><small>{{sceneId==='hash'?`槽 ${i}`:sceneId==='stack'&&i===step.values.length-1?'栈顶':sceneId==='queue'&&i===0?'队首':sceneId==='queue'&&i===step.values.length-1?'队尾':sceneId==='deque'&&i===0?'左端':sceneId==='deque'&&i===step.values.length-1?'右端':i}}</small><strong>{{sceneId==='hash'&&value<0?'空':value}}</strong></div></div><div v-if="step.rows&&sceneId!=='tree'&&sceneId!=='traversal'&&sceneId!=='heap'&&sceneId!=='hanoi'" class="teaching-table" :class="{'queen-board':sceneId==='queens'}"><table><tbody><tr v-for="(row,r) in step.rows" :key="r"><th v-if="step.labels">{{step.labels[r]}}</th><td v-for="(value,c) in row" :key="c" :class="{queen:sceneId==='queens'&&value===1,candidate:sceneId==='queens'&&value===2,active:sceneId==='knapsack'&&step.variables['物品']===r&&step.variables['容量']===c}" :aria-label="sceneId==='queens'?`${r+1} 行 ${c+1} 列 ${value===1?'皇后':value===2?'检查位置':'空格'}`:undefined">{{sceneId==='queens'?(value===1?'♛':value===2?'?':'·'):Number.isInteger(value)?value:Math.round(value*1000)/1000}}</td></tr></tbody></table></div><pre v-if="step.code" class="teaching-code"><div v-for="(line,i) in step.code.split('\n')" :key="i" :class="{active:i+1===step.line}">{{i+1}}  {{line}}</div></pre></div>
<p class="teaching-explanation" role="status" aria-live="polite">{{step.explanation}}</p><dl class="teaching-variables"><template v-for="(v,k) in step.variables" :key="k"><dt>{{k}}</dt><dd>{{typeof v==='object'?JSON.stringify(v):v}}</dd></template></dl><details v-if="step.result!==undefined"><summary>当前结果</summary><pre>{{JSON.stringify(step.result,null,2)}}</pre></details></section></template>
<style>.teaching-scene{padding:16px;color:#e7f4fc}.teaching-scene>p{font-size:13px;line-height:1.8}.teaching-scene textarea{display:block;width:100%;font:14px 'JetBrains Mono';background:#0b1b2a;color:#e7f4fc;border:1px solid #6a93ab;padding:12px;margin:12px 0}.teaching-controls{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:18px 0}.teaching-controls button{min-height:44px}.teaching-stage{padding:24px 12px;background:#081a28;border:1px solid #446a83;border-radius:12px;overflow:auto;min-height:170px}.teaching-values{display:flex;gap:8px;flex-wrap:wrap;justify-content:center}.teaching-values>div{min-width:46px;padding:8px;display:flex;flex-direction:column;text-align:center;background:#214052;border:1px solid #6c9bb6;border-radius:5px}.teaching-values small{font-size:10px;color:#acbdcc}.teaching-values strong{font-size:22px}.teaching-stage .active{outline:2px solid #e3c17d;background:#605332}.teaching-table{overflow:auto}.teaching-table table{border-collapse:collapse;margin:auto}.teaching-table td,.teaching-table th{padding:8px;min-width:32px;text-align:center;border:1px solid #4f6b81;font-size:12px}.queen-board td{font-size:24px;width:38px;height:38px}.queen-board .queen{background:#236571;color:#f4e8bf}.queen-board .candidate{background:#6d3d35}.teaching-variables{display:grid;grid-template-columns:auto 1fr;gap:8px;font-size:13px}.teaching-variables dd{margin:0;overflow-wrap:anywhere}.teaching-explanation{padding:14px;border-left:3px solid #e3c17d;background:#193245}.teaching-code{font:13px/2 'JetBrains Mono';white-space:pre-wrap}.hanoi-towers{display:flex;gap:12px;justify-content:space-around;min-height:180px}.hanoi-towers>div{flex:1;display:flex;align-items:center;justify-content:flex-end;flex-direction:column;border-bottom:4px solid #7e99ad;min-width:130px;gap:5px}.hanoi-towers strong{margin-bottom:auto}.hanoi-towers span{height:24px;background:#396e83;border:1px solid #91c6d5;border-radius:5px;text-align:center;font-size:12px}.hanoi-towers small{padding:20px;color:#a7bdca}
</style>
